 public function __construct(string $appName,IRequest $request,private IDBConnection $db,private IURLGenerator $url,private IUserSession $session,private IUserManager $userManager,private NumberService $numbers,private FolderService $folders,private PdfService $pdf,private PermissionService $permissions,private IGroupManager $groupManager){parent::__construct($appName,$request);}
 #[NoAdminRequired,NoCSRFRequired] public function reports():TemplateResponse{$this->permissions->assert('reports');$this->syncAllReportFiles();$projects=$this->rows('re_erp_projects','project_no');$projectId=(int)$this->request->getParam('projectId',0);if($projectId<=0&&count($projects)===1){$projectId=(int)$projects[0]['id'];}$availableEntries=$projectId>0?$this->availableTimeEntries($projectId):[];return $this->page('reports','Rapporte',$this->reportRows(),['projects'=>$projects,'selectedProjectId'=>$projectId,'availableEntries'=>$availableEntries]);}
 #[NoAdminRequired] public function saveReport(int $projectId,string $reportDate,string $title,?string $description=null,array $entryIds=[]):RedirectResponse{$project=$this->one('re_erp_projects',$projectId);if(!$project)throw new \InvalidArgumentException('Projekt nicht gefunden.');$title=trim($title);if($title==='')throw new \InvalidArgumentException('Titel fehlt.');$number=$this->numbers->next('report');$path=$this->folders->ensureReportFolder((string)$project['folder_path'],$number,$title);$id=$this->insert('re_erp_reports',['customer_id'=>$project['customer_id'],'project_id'=>$projectId,'report_no'=>$number,'report_date'=>$reportDate,'title'=>$title,'description'=>$description,'status'=>'Entwurf','folder_path'=>$path,'created_by'=>$this->uid(),'created_at'=>date('Y-m-d H:i:s'),'updated_at'=>date('Y-m-d H:i:s')]);foreach($entryIds as $raw){$entryId=(int)$raw;if($entryId<=0)continue;$entry=$this->timeEntry($entryId);if(!$entry||$entry['imported_to_report_id']!==null||(int)$entry['project_id']!==$projectId)continue;$this->insert('re_erp_report_hours',['report_id'=>$id,'user_id'=>$entry['user_id'],'hours'=>$entry['hours'],'activity'=>$entry['activity'],'work_date'=>$entry['work_date']??null,'source_entry_id'=>$entryId]);$this->update('re_erp_workday_entries',$entryId,['imported_to_report_id'=>$id]);}$this->writeReportSnapshot($id);return $this->go('reinhardterp.module.reportDetail',['id'=>$id]);}
 #[NoAdminRequired,NoCSRFRequired] public function reportDetail(int $id):TemplateResponse{$this->writeReportSnapshot($id);$report=$this->one('re_erp_reports',$id);if(!$report)throw new \OCP\AppFramework\Http\NotFoundResponse();$project=$this->one('re_erp_projects',(int)$report['project_id']);$customer=$project?$this->one('re_erp_customers',(int)$project['customer_id']):null;return new TemplateResponse($this->appName,'report_detail',['report'=>$report,'project'=>$project,'customer'=>$customer,'hours'=>$this->where('re_erp_report_hours','report_id',$id,'id'),'items'=>$this->where('re_erp_report_items','report_id',$id,'id'),'files'=>$this->where('re_erp_report_files','report_id',$id,'id'),'materials'=>$this->rows('re_erp_materials','name'),'users'=>$this->usersArray(),'availableEntries'=>$this->availableTimeEntries((int)$report['project_id'])]);}
 #[NoAdminRequired,NoCSRFRequired] public function reportPrint(int $id):TemplateResponse{$report=$this->one('re_erp_reports',$id);if(!$report)throw new \OCP\AppFramework\Http\NotFoundResponse();$project=$this->one('re_erp_projects',(int)$report['project_id']);$customer=$project?$this->one('re_erp_customers',(int)$project['customer_id']):null;$logo=$this->folders->companyLogo();return new TemplateResponse($this->appName,'report_print',['report'=>$report,'project'=>$project,'customer'=>$customer,'hours'=>$this->where('re_erp_report_hours','report_id',$id,'id'),'items'=>$this->where('re_erp_report_items','report_id',$id,'id'),'logoDataUri'=>$logo?'data:'.$logo['mime'].';base64,'.base64_encode($logo['content']):null],'blank');}
 #[NoAdminRequired] public function updateReport(int $id,string $title,string $reportDate,?string $description=null,?string $customerNote=null,?string $signedBy=null,?string $signatureData=null,?string $actionMode=null):RedirectResponse{$report=$this->one('re_erp_reports',$id);$this->assertEditable($report);$data=['title'=>trim($title),'report_date'=>$reportDate,'description'=>$description,'customer_note'=>$customerNote,'updated_at'=>date('Y-m-d H:i:s')];$hasSignature=false;if($signatureData&&str_starts_with($signatureData,'data:image/png;base64,')){$raw=base64_decode(substr($signatureData,strpos($signatureData,',')+1),true);if($raw!==false&&strlen($raw)>100){$path=$this->folders->write((string)$report['folder_path'],'Unterschrift.png',$raw);$data['signature_path']=$path;$data['signature_data']=$signatureData;$data['signature_mime']='image/png';$data['signed_by']=trim((string)$signedBy)?:null;$data['signed_at']=date('Y-m-d H:i:s');$data['status']='Unterschrieben';$hasSignature=true;}}if($actionMode==='sign'){if(!$hasSignature&&empty($report['signature_data']))throw new \InvalidArgumentException('Bitte zuerst eine Unterschrift zeichnen.');if(trim((string)$signedBy)===''&&empty($report['signed_by']))throw new \InvalidArgumentException('Bitte den Namen der unterschreibenden Person eintragen.');$data['status']='Unterschrieben';$data['locked']=1;$data['finalized_at']=date('Y-m-d H:i:s');}$this->update('re_erp_reports',$id,$data);$this->writeReportSnapshot($id);return $this->go('reinhardterp.module.reportDetail',['id'=>$id]);}
 #[NoAdminRequired] public function finalizeReport(int $id):RedirectResponse{$report=$this->one('re_erp_reports',$id);if(!$report)throw new \InvalidArgumentException('Rapport nicht gefunden.');$status=!empty($report['signature_data'])?'Unterschrieben':'Fertiggestellt';$this->update('re_erp_reports',$id,['status'=>$status,'locked'=>1,'finalized_at'=>date('Y-m-d H:i:s'),'updated_at'=>date('Y-m-d H:i:s')]);$this->writeReportSnapshot($id);return $this->go('reinhardterp.module.reportDetail',['id'=>$id]);}
 #[NoAdminRequired] public function reopenReport(int $id):RedirectResponse{$this->update('re_erp_reports',$id,['status'=>'Entwurf','locked'=>0,'finalized_at'=>null,'updated_at'=>date('Y-m-d H:i:s')]);$this->writeReportSnapshot($id);return $this->go('reinhardterp.module.reportDetail',['id'=>$id]);}
 #[NoAdminRequired] public function addReportHour(int $reportId,string $userId,float $hours,?string $activity=null,?string $workDate=null):RedirectResponse{$this->assertEditable($this->one('re_erp_reports',$reportId));if($hours<=0)throw new \InvalidArgumentException('Stunden müssen größer als 0 sein.');$this->insert('re_erp_report_hours',['report_id'=>$reportId,'user_id'=>$userId,'hours'=>$hours,'activity'=>$activity,'work_date'=>$workDate?:null]);$this->writeReportSnapshot($reportId);return $this->go('reinhardterp.module.reportDetail',['id'=>$reportId]);}
 #[NoAdminRequired] public function addReportItem(int $reportId,?int $materialId,?string $description,float $quantity,?string $unit=null,?string $notes=null):RedirectResponse{$this->assertEditable($this->one('re_erp_reports',$reportId));if($quantity<=0)throw new \InvalidArgumentException('Menge muss größer als 0 sein.');if(($description===null||trim($description)==='')&&$materialId){$m=$this->one('re_erp_materials',$materialId);$description=$m['name']??'';$unit=$unit?:($m['unit']??null);}$this->insert('re_erp_report_items',['report_id'=>$reportId,'material_id'=>$materialId,'description'=>trim((string)$description),'quantity'=>$quantity,'unit'=>$unit,'notes'=>$notes]);$this->writeReportSnapshot($reportId);return $this->go('reinhardterp.module.reportDetail',['id'=>$reportId]);}
 #[NoAdminRequired] public function deleteReportHour(int $reportId,int $id):RedirectResponse{$this->assertEditable($this->one('re_erp_reports',$reportId));$hour=$this->one('re_erp_report_hours',$id);if($hour&&!empty($hour['source_entry_id']))$this->update('re_erp_workday_entries',(int)$hour['source_entry_id'],['imported_to_report_id'=>null]);$this->delete('re_erp_report_hours',$id);$this->writeReportSnapshot($reportId);return $this->go('reinhardterp.module.reportDetail',['id'=>$reportId]);}
 #[NoAdminRequired] public function deleteReportItem(int $reportId,int $id):RedirectResponse{$this->assertEditable($this->one('re_erp_reports',$reportId));$this->delete('re_erp_report_items',$id);$this->writeReportSnapshot($reportId);return $this->go('reinhardterp.module.reportDetail',['id'=>$reportId]);}
 #[NoAdminRequired] public function importTimeEntries(int $reportId,array $entryIds=[]):RedirectResponse{$this->assertEditable($this->one('re_erp_reports',$reportId));foreach($entryIds as $raw){$entryId=(int)$raw;if($entryId<=0)continue;$entry=$this->timeEntry($entryId);if(!$entry||$entry['imported_to_report_id']!==null)continue;$this->insert('re_erp_report_hours',['report_id'=>$reportId,'user_id'=>$entry['user_id'],'hours'=>$entry['hours'],'activity'=>$entry['activity'],'work_date'=>$entry['work_date']??null,'source_entry_id'=>$entryId]);$this->update('re_erp_workday_entries',$entryId,['imported_to_report_id'=>$reportId]);}$this->writeReportSnapshot($reportId);return $this->go('reinhardterp.module.reportDetail',['id'=>$reportId]);}
 #[NoAdminRequired] public function uploadReportFile(int $reportId):RedirectResponse{$report=$this->one('re_erp_reports',$reportId);$file=$this->request->getUploadedFile('attachment');if(is_array($file)&&($file['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_OK){$name=(string)($file['name']??'Anhang');$path=$this->folders->writeFromLocalFile((string)$report['folder_path'].'/Anhaenge',$name,(string)$file['tmp_name']);$this->insert('re_erp_report_files',['report_id'=>$reportId,'path'=>$path,'created_at'=>date('Y-m-d H:i:s')]);}return $this->go('reinhardterp.module.reportDetail',['id'=>$reportId]);}
 #[NoAdminRequired,NoCSRFRequired] public function materials():TemplateResponse{$this->permissions->assert('materials');return $this->page('materials','Material',$this->rows('re_erp_materials','name'));}
 #[NoAdminRequired] public function saveMaterial(?string $articleNo,string $name,?string $materialGroup=null,?string $unit=null,float $price=0):RedirectResponse{$articleNo=trim((string)$articleNo);if($articleNo==='')$articleNo=$this->numbers->next('material');$this->insert('re_erp_materials',['article_no'=>$articleNo,'name'=>trim($name),'material_group'=>$materialGroup,'unit'=>$unit,'price'=>$price,'active'=>1,'created_at'=>date('Y-m-d H:i:s')]);return $this->go('reinhardterp.module.materials');}
 #[NoAdminRequired,NoCSRFRequired] public function workdays(?string $week=null):TemplateResponse{$this->permissions->assert('time');$weekStart=$this->normalizeWeekStart($week);$weekEnd=date('Y-m-d',strtotime($weekStart.' +6 days'));return new TemplateResponse($this->appName,'workdays',['rows'=>$this->workdayRows($weekStart,$weekEnd),'projects'=>$this->rows('re_erp_projects','project_no'),'users'=>$this->activeErpUsers(),'weekStart'=>$weekStart,'weekEnd'=>$weekEnd,'weekSummary'=>$this->weeklySummary($weekStart,$weekEnd),'activeTimers'=>$this->activeTimers()]);}
 #[NoAdminRequired,NoCSRFRequired] public function timeEvaluation(?string $from=null,?string $to=null,?int $customerId=null,?int $projectId=null,?string $userId=null,?string $billingStatus=null,float $hourlyRate=0,?string $message=null,?string $messageType=null):TemplateResponse{$this->permissions->assert('time_billing');$from=$from&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)?$from:date('Y-m-01');$to=$to&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)?$to:date('Y-m-d');if($to<$from){[$from,$to]=[$to,$from];}$status=in_array($billingStatus,['open','reserved','billed','all'],true)?$billingStatus:'open';$users=$this->activeErpUsers();$userNames=[];foreach($users as $u){$userNames[(string)$u['uid']]=(string)$u['displayName'];}$rows=$this->timeEvaluationRows($from,$to,$customerId,$projectId,$userId,$status);$hours=0.0;$amount=0.0;$byProject=[];$byCustomer=[];$byUser=[];foreach($rows as &$row){$h=(float)$row['hours'];$rateSource='Kein Stundensatz';if($row['billing_rate']!==null){$rate=(float)$row['billing_rate'];$rateSource='Festgeschrieben';}elseif($row['special_hourly_rate']!==null){$rate=(float)$row['special_hourly_rate'];$rateSource='Projekt-Sonderpreis';}elseif($row['individual_hourly_rate']!==null){$rate=(float)$row['individual_hourly_rate'];$rateSource='Mitarbeiter-Sonderpreis';}elseif($row['group_sales_rate']!==null){$rate=(float)$row['group_sales_rate'];$rateSource=(string)($row['hourly_rate_name']??'Stundengruppe');}else{$rate=$hourlyRate;$rateSource=$hourlyRate>0?'Manueller Ersatzsatz':'Kein Stundensatz';}$row['effective_rate']=$rate;$row['rate_source']=$rateSource;$row['amount']=$h*$rate;$row['user_display_name']=$userNames[(string)$row['user_id']]??(string)$row['user_id'];$hours+=$h;$amount+=$row['amount'];$pk=trim((string)($row['project_no']??'Ohne Projekt').' '.(string)($row['project_title']??''));$ck=trim((string)($row['customer_no']??'').' '.(string)($row['customer_name']??'Ohne Kunde'));$uk=$row['user_display_name'];$byProject[$pk]=($byProject[$pk]??0)+$h;$byCustomer[$ck]=($byCustomer[$ck]??0)+$h;$byUser[$uk]=($byUser[$uk]??0)+$h;}unset($row);arsort($byProject);arsort($byCustomer);arsort($byUser);return new TemplateResponse($this->appName,'time_evaluation',['rows'=>$rows,'customers'=>$this->rows('re_erp_customers','name'),'projects'=>$this->rows('re_erp_projects','project_no'),'users'=>$users,'filters'=>['from'=>$from,'to'=>$to,'customerId'=>$customerId,'projectId'=>$projectId,'userId'=>$userId,'billingStatus'=>$status,'hourlyRate'=>$hourlyRate],'summary'=>['hours'=>$hours,'amount'=>$amount,'byProject'=>$byProject,'byCustomer'=>$byCustomer,'byUser'=>$byUser],'message'=>$message,'messageType'=>in_array($messageType,['success','warning','error'],true)?$messageType:'success']);}
 #[NoAdminRequired] public function updateBillingStatus(array $entryIds=[],string $billingStatus='open',?string $billingReference=null,float $billingRate=0,?string $from=null,?string $to=null,?int $customerId=null,?int $projectId=null,?string $userId=null,?string $returnBillingStatus=null,float $hourlyRate=0):RedirectResponse{$this->permissions->assert('time_billing');$return=['from'=>$from,'to'=>$to,'customerId'=>$customerId,'projectId'=>$projectId,'userId'=>$userId,'billingStatus'=>$returnBillingStatus,'hourlyRate'=>$hourlyRate];if(!in_array($billingStatus,['open','reserved','billed'],true)){$return+=['message'=>'Ungültiger Abrechnungsstatus.','messageType'=>'error'];return $this->go('reinhardterp.module.timeEvaluation',$return);}$ids=array_values(array_unique(array_filter(array_map('intval',$entryIds),fn($id)=>$id>0)));if($ids===[]){$return+=['message'=>'Bitte mindestens einen Zeiteintrag auswählen.','messageType'=>'warning'];return $this->go('reinhardterp.module.timeEvaluation',$return);}$reference=trim((string)$billingReference);if($billingStatus==='billed'&&$reference===''){$return+=['message'=>'Für abgerechnete Zeiten ist eine Rechnungsnummer oder Referenz erforderlich.','messageType'=>'warning'];return $this->go('reinhardterp.module.timeEvaluation',$return);}foreach($ids as $id){$rate=null;if($billingStatus!=='open'){$row=$this->timeBillingRow($id);$rate=$billingRate>0?$billingRate:$this->automaticRate($row);if($rate===null||$rate<=0){$return+=['message'=>'Für mindestens einen Eintrag fehlt ein gültiger Stundensatz. Bitte Stundengruppe oder Ersatzsatz hinterlegen.','messageType'=>'warning'];return $this->go('reinhardterp.module.timeEvaluation',$return);}}$data=['billing_status'=>$billingStatus,'billing_reference'=>$billingStatus==='open'?null:($reference!==''?$reference:null),'billing_rate'=>$billingStatus==='open'?null:$rate,'billed_at'=>$billingStatus==='billed'?date('Y-m-d H:i:s'):null,'billed_by'=>$billingStatus==='billed'?$this->uid():null];$this->update('re_erp_workday_entries',$id,$data);}$labels=['open'=>'wieder geöffnet','reserved'=>'für die Rechnung vorgemerkt','billed'=>'als abgerechnet markiert'];$return+=['message'=>count($ids).' Zeiteintrag/Zeiteinträge wurden '.$labels[$billingStatus].'.','messageType'=>'success'];return $this->go('reinhardterp.module.timeEvaluation',$return);}
 #[NoAdminRequired] public function saveWorkday(string $workDate,int $projectId,string $userId,float $hours=0,string $activity='',?string $startTime=null,?string $endTime=null,int $breakMinutes=0,?string $notes=null):RedirectResponse{$this->permissions->assert('time');if(!$this->permissions->isEnabled($userId))throw new \InvalidArgumentException('Der gewählte Mitarbeiter ist für das ERP gesperrt.');if($hours<=0&&$startTime&&$endTime){$start=strtotime($workDate.' '.$startTime);$end=strtotime($workDate.' '.$endTime);if($end<$start)$end+=86400;$hours=max(0,(($end-$start)/3600)-($breakMinutes/60));}$hours=round($hours,2);if($hours<=0)throw new \InvalidArgumentException('Stunden oder Beginn und Ende müssen angegeben werden.');if(trim($activity)==='')throw new \InvalidArgumentException('Tätigkeit fehlt.');$enteredBy=$this->uid();$workdayId=$this->insert('re_erp_workdays',['user_id'=>$userId,'work_date'=>$workDate,'start_time'=>$startTime,'end_time'=>$endTime,'break_minutes'=>$breakMinutes,'notes'=>$notes,'entered_by'=>$enteredBy,'updated_by'=>$enteredBy,'created_at'=>date('Y-m-d H:i:s'),'updated_at'=>date('Y-m-d H:i:s')]);$project=$this->one('re_erp_projects',$projectId);if(!$project)throw new \InvalidArgumentException('Projekt nicht gefunden.');$this->insert('re_erp_workday_entries',['workday_id'=>$workdayId,'customer_id'=>$project['customer_id']??null,'project_id'=>$projectId,'activity'=>trim($activity),'hours'=>$hours,'imported_to_report_id'=>null,'created_at'=>date('Y-m-d H:i:s')]);return $this->go('reinhardterp.module.workdays');}
 #[NoAdminRequired] public function deleteWorkday(int $id):RedirectResponse{$entries=$this->where('re_erp_workday_entries','workday_id',$id,'id');foreach($entries as $entry){if(!empty($entry['imported_to_report_id']))throw new \InvalidArgumentException('Bereits in einen Rapport übernommene Zeiten können nicht gelöscht werden.');}$qb=$this->db->getQueryBuilder();$qb->delete('re_erp_workday_entries')->where($qb->expr()->eq('workday_id',$qb->createNamedParameter($id)))->executeStatement();$this->delete('re_erp_workdays',$id);return $this->go('reinhardterp.module.workdays');}
 #[NoAdminRequired] public function startTimer(int $projectId,string $userId,string $activity):RedirectResponse{$this->permissions->assert('time');if(!$this->permissions->isEnabled($userId))throw new \InvalidArgumentException('Der gewählte Mitarbeiter ist für das ERP gesperrt.');if(trim($activity)==='')throw new \InvalidArgumentException('Tätigkeit fehlt.');if(!$this->one('re_erp_projects',$projectId))throw new \InvalidArgumentException('Projekt nicht gefunden.');$qb=$this->db->getQueryBuilder();$qb->select('id')->from('re_erp_time_timers')->where($qb->expr()->eq('user_id',$qb->createNamedParameter($userId)))->andWhere($qb->expr()->in('status',[$qb->createNamedParameter('running'),$qb->createNamedParameter('paused')]));if($qb->executeQuery()->fetchOne())throw new \InvalidArgumentException('Für diesen Mitarbeiter läuft bereits eine Zeiterfassung.');$now=date('Y-m-d H:i:s');$this->insert('re_erp_time_timers',['user_id'=>$userId,'project_id'=>$projectId,'activity'=>trim($activity),'started_at'=>$now,'paused_at'=>null,'pause_seconds'=>0,'status'=>'running','created_by'=>$this->uid(),'created_at'=>$now]);return $this->go('reinhardterp.module.workdays');}
 #[NoAdminRequired] public function pauseTimer(int $id):RedirectResponse{$this->permissions->assert('time');$timer=$this->one('re_erp_time_timers',$id);if(!$timer||$timer['status']!=='running')throw new \InvalidArgumentException('Der Timer läuft nicht.');$this->update('re_erp_time_timers',$id,['status'=>'paused','paused_at'=>date('Y-m-d H:i:s')]);return $this->go('reinhardterp.module.workdays');}
 #[NoAdminRequired] public function resumeTimer(int $id):RedirectResponse{$this->permissions->assert('time');$timer=$this->one('re_erp_time_timers',$id);if(!$timer||$timer['status']!=='paused'||empty($timer['paused_at']))throw new \InvalidArgumentException('Der Timer ist nicht pausiert.');$extra=max(0,time()-strtotime((string)$timer['paused_at']));$this->update('re_erp_time_timers',$id,['status'=>'running','paused_at'=>null,'pause_seconds'=>(int)$timer['pause_seconds']+$extra]);return $this->go('reinhardterp.module.workdays');}
 #[NoAdminRequired] public function stopTimer(int $id,?string $notes=null):RedirectResponse{$this->permissions->assert('time');$timer=$this->one('re_erp_time_timers',$id);if(!$timer||!in_array($timer['status'],['running','paused'],true))throw new \InvalidArgumentException('Timer nicht gefunden oder bereits beendet.');$now=time();$pause=(int)$timer['pause_seconds'];if($timer['status']==='paused'&&!empty($timer['paused_at']))$pause+=max(0,$now-strtotime((string)$timer['paused_at']));$start=strtotime((string)$timer['started_at']);$seconds=max(60,$now-$start-$pause);$hours=round($seconds/3600,2);$project=$this->one('re_erp_projects',(int)$timer['project_id']);if(!$project)throw new \InvalidArgumentException('Projekt nicht gefunden.');$workDate=date('Y-m-d',$start);$workdayId=$this->insert('re_erp_workdays',['user_id'=>$timer['user_id'],'work_date'=>$workDate,'start_time'=>date('H:i',$start),'end_time'=>date('H:i',$now),'break_minutes'=>(int)round($pause/60),'notes'=>$notes,'entered_by'=>$timer['created_by'],'updated_by'=>$this->uid(),'created_at'=>date('Y-m-d H:i:s'),'updated_at'=>date('Y-m-d H:i:s')]);$this->insert('re_erp_workday_entries',['workday_id'=>$workdayId,'customer_id'=>$project['customer_id']??null,'project_id'=>$timer['project_id'],'activity'=>$timer['activity'],'hours'=>$hours,'imported_to_report_id'=>null,'created_at'=>date('Y-m-d H:i:s')]);$this->update('re_erp_time_timers',$id,['status'=>'stopped','paused_at'=>null]);return $this->go('reinhardterp.module.workdays');}

