 #[NoAdminRequired,NoCSRFRequired] public function invoicePreparation(?int $customerId=null,?int $projectId=null,?string $message=null,?string $messageType=null):TemplateResponse{$this->permissions->assert('invoices');$rows=$this->timeEvaluationRows('2000-01-01','2999-12-31',$customerId,$projectId,null,'reserved');$users=$this->activeErpUsers();$names=[];foreach($users as $u)$names[(string)$u['uid']]=(string)$u['displayName'];$groups=[];foreach($rows as &$r){$r['user_display_name']=$names[(string)$r['user_id']]??(string)$r['user_id'];$r['effective_rate']=$r['billing_rate']!==null?(float)$r['billing_rate']:(float)($this->automaticRate($r)??0);$r['amount']=(float)$r['hours']*$r['effective_rate'];$key=(int)$r['customer_id'].'-'.(int)$r['project_id'];if(!isset($groups[$key]))$groups[$key]=['customer_id'=>(int)$r['customer_id'],'project_id'=>(int)$r['project_id'],'customer'=>trim((string)($r['customer_no']??'').' '.(string)($r['customer_name']??'')),'project'=>trim((string)($r['project_no']??'').' '.(string)($r['project_title']??'')),'hours'=>0.0,'amount'=>0.0,'count'=>0];$groups[$key]['hours']+=(float)$r['hours'];$groups[$key]['amount']+=$r['amount'];$groups[$key]['count']++;}unset($r);return new TemplateResponse($this->appName,'invoice_preparation',['rows'=>$rows,'groups'=>array_values($groups),'filters'=>['customerId'=>$customerId,'projectId'=>$projectId],'customers'=>$this->rows('re_erp_customers','name'),'projects'=>$this->rows('re_erp_projects','project_no'),'batches'=>$this->billingBatches(),'message'=>$message,'messageType'=>in_array($messageType,['success','warning','error'],true)?$messageType:'success']);}
 #[NoAdminRequired] public function createBillingBatch(array $entryIds=[],string $title='Abrechnungsvorbereitung',?string $notes=null):RedirectResponse{$this->permissions->assert('invoices');$ids=array_values(array_unique(array_filter(array_map('intval',$entryIds),fn($id)=>$id>0)));if($ids===[])return $this->go('reinhardterp.module.invoicePreparation',['message'=>'Bitte mindestens einen vorgemerkten Zeiteintrag auswählen.','messageType'=>'warning']);$rows=[];foreach($ids as $id){$r=$this->invoiceTimeRow($id);if(!$r||$r['billing_status']!=='reserved')continue;$r['effective_rate']=$r['billing_rate']!==null?(float)$r['billing_rate']:(float)($this->automaticRate($r)??0);if($r['effective_rate']<=0)return $this->go('reinhardterp.module.invoicePreparation',['message'=>'Für mindestens einen Eintrag fehlt ein Stundensatz.','messageType'=>'warning']);$rows[]=$r;}if($rows===[])return $this->go('reinhardterp.module.invoicePreparation',['message'=>'Keine gültigen vorgemerkten Zeiten ausgewählt.','messageType'=>'warning']);$customerId=(int)$rows[0]['customer_id'];$projectId=(int)$rows[0]['project_id'];foreach($rows as $r)if((int)$r['customer_id']!==$customerId||(int)$r['project_id']!==$projectId)return $this->go('reinhardterp.module.invoicePreparation',['message'=>'Ein Abrechnungspaket darf nur Zeiten desselben Kunden und Projekts enthalten.','messageType'=>'warning']);$customer=$this->one('re_erp_customers',$customerId);if(!$customer)throw new \InvalidArgumentException('Kunde nicht gefunden.');$hours=array_sum(array_map(fn($r)=>(float)$r['hours'],$rows));$amount=array_sum(array_map(fn($r)=>(float)$r['hours']*(float)$r['effective_rate'],$rows));$id=$this->insert('re_erp_billing_batches',['batch_no'=>'TEMP','customer_id'=>$customerId,'project_id'=>$projectId?:null,'title'=>trim($title)?:'Abrechnungsvorbereitung','notes'=>$notes,'total_hours'=>$hours,'net_amount'=>$amount,'folder_path'=>null,'status'=>'prepared','created_by'=>$this->uid(),'created_at'=>date('Y-m-d H:i:s')]);$batchNo='AB-'.date('Y').'-'.str_pad((string)$id,4,'0',STR_PAD_LEFT);$folder=$this->folders->ensureBillingBatchFolder((string)$customer['folder_path'],$batchNo);$this->update('re_erp_billing_batches',$id,['batch_no'=>$batchNo,'folder_path'=>$folder]);foreach($rows as $r){$this->insert('re_erp_billing_batch_items',['batch_id'=>$id,'entry_id'=>(int)$r['id'],'work_date'=>$r['work_date'],'user_id'=>$r['user_id'],'activity'=>$r['activity'],'hours'=>$r['hours'],'hourly_rate'=>$r['effective_rate'],'amount'=>(float)$r['hours']*(float)$r['effective_rate']]);$this->update('re_erp_workday_entries',(int)$r['id'],['billing_batch_id'=>$id,'billing_reference'=>$batchNo]);}$this->writeBillingBatchSnapshot($id);return $this->go('reinhardterp.module.billingBatchDetail',['id'=>$id]);}
 #[NoAdminRequired,NoCSRFRequired] public function billingBatchDetail(int $id):TemplateResponse{$this->permissions->assert('invoices');$batch=$this->one('re_erp_billing_batches',$id);if(!$batch)throw new \InvalidArgumentException('Abrechnungspaket nicht gefunden.');return new TemplateResponse($this->appName,'billing_batch_detail',['batch'=>$batch,'customer'=>$this->one('re_erp_customers',(int)$batch['customer_id']),'project'=>$batch['project_id']?$this->one('re_erp_projects',(int)$batch['project_id']):null,'items'=>$this->billingBatchItems($id)]);}
 #[NoAdminRequired,NoCSRFRequired] public function billingBatchPrint(int $id):TemplateResponse{$this->permissions->assert('invoices');$batch=$this->one('re_erp_billing_batches',$id);if(!$batch)throw new \InvalidArgumentException('Abrechnungspaket nicht gefunden.');$logo=$this->folders->companyLogo();return new TemplateResponse($this->appName,'billing_batch_print',['batch'=>$batch,'customer'=>$this->one('re_erp_customers',(int)$batch['customer_id']),'project'=>$batch['project_id']?$this->one('re_erp_projects',(int)$batch['project_id']):null,'items'=>$this->billingBatchItems($id),'logoDataUri'=>$logo?'data:'.$logo['mime'].';base64,'.base64_encode($logo['content']):null],'blank');}
 #[NoAdminRequired] public function createInvoice(array $entryIds=[],string $grouping='detailed',float $vatRate=19):RedirectResponse{$this->permissions->assert('invoices');$ids=array_values(array_unique(array_filter(array_map('intval',$entryIds),fn($id)=>$id>0)));if($ids===[])return $this->go('reinhardterp.module.invoicePreparation',['message'=>'Bitte mindestens einen vorgemerkten Zeiteintrag auswählen.','messageType'=>'warning']);$rows=[];foreach($ids as $id){$r=$this->invoiceTimeRow($id);if(!$r||$r['billing_status']!=='reserved')continue;$r['effective_rate']=$r['billing_rate']!==null?(float)$r['billing_rate']:(float)($this->automaticRate($r)??0);if($r['effective_rate']<=0)return $this->go('reinhardterp.module.invoicePreparation',['message'=>'Für mindestens einen Eintrag fehlt ein Stundensatz.','messageType'=>'warning']);$rows[]=$r;}if($rows===[])return $this->go('reinhardterp.module.invoicePreparation',['message'=>'Keine gültigen vorgemerkten Zeiten ausgewählt.','messageType'=>'warning']);$customerId=(int)$rows[0]['customer_id'];$projectId=(int)$rows[0]['project_id'];foreach($rows as $r)if((int)$r['customer_id']!==$customerId||(int)$r['project_id']!==$projectId)return $this->go('reinhardterp.module.invoicePreparation',['message'=>'Eine Rechnung darf nur Zeiten desselben Kunden und Projekts enthalten.','messageType'=>'warning']);$customer=$this->one('re_erp_customers',$customerId);if(!$customer)throw new \InvalidArgumentException('Kunde nicht gefunden.');$invoiceNo=$this->numbers->next('invoice');$folder=$this->folders->ensureInvoiceFolder((string)$customer['folder_path'],$invoiceNo);$vat=max(0,min(100,$vatRate));$items=[];if($grouping==='total'){$hours=array_sum(array_map(fn($r)=>(float)$r['hours'],$rows));$total=array_sum(array_map(fn($r)=>(float)$r['hours']*(float)$r['effective_rate'],$rows));$items[]=['description'=>'Arbeitsleistungen gemäß Zeiterfassung','quantity'=>$hours,'unit'=>'Std.','unit_price'=>$hours>0?$total/$hours:0,'total_price'=>$total,'source_id'=>null];}elseif($grouping==='employee'){$bucket=[];foreach($rows as $r){$k=$r['user_id'].'|'.$r['effective_rate'];if(!isset($bucket[$k]))$bucket[$k]=['description'=>'Arbeitsleistungen '.($r['user_id']??''),'quantity'=>0.0,'unit'=>'Std.','unit_price'=>(float)$r['effective_rate'],'total_price'=>0.0,'source_id'=>null];$bucket[$k]['quantity']+=(float)$r['hours'];$bucket[$k]['total_price']+=(float)$r['hours']*(float)$r['effective_rate'];}$items=array_values($bucket);}else{foreach($rows as $r)$items[]=['description'=>date('d.m.Y',strtotime((string)$r['work_date'])).' – '.(string)$r['activity'],'quantity'=>(float)$r['hours'],'unit'=>'Std.','unit_price'=>(float)$r['effective_rate'],'total_price'=>(float)$r['hours']*(float)$r['effective_rate'],'source_id'=>(int)$r['id']];}$net=array_sum(array_column($items,'total_price'));$gross=$net*(1+$vat/100);$invoiceId=$this->insert('re_erp_invoices',['invoice_no'=>$invoiceNo,'customer_id'=>$customerId,'project_id'=>$projectId?:null,'invoice_date'=>date('Y-m-d'),'status'=>'draft','net_amount'=>$net,'vat_rate'=>$vat,'gross_amount'=>$gross,'folder_path'=>$folder,'created_by'=>$this->uid(),'created_at'=>date('Y-m-d H:i:s')]);foreach($items as $item)$this->insert('re_erp_invoice_items',['invoice_id'=>$invoiceId,'source_type'=>'time','source_id'=>$item['source_id'],'description'=>$item['description'],'quantity'=>$item['quantity'],'unit'=>$item['unit'],'unit_price'=>$item['unit_price'],'total_price'=>$item['total_price']]);foreach($rows as $r)$this->update('re_erp_workday_entries',(int)$r['id'],['billing_status'=>'billed','billing_reference'=>$invoiceNo,'invoice_id'=>$invoiceId,'billed_at'=>date('Y-m-d H:i:s'),'billed_by'=>$this->uid()]);$this->writeInvoiceSnapshot($invoiceId);return $this->go('reinhardterp.module.invoiceDetail',['id'=>$invoiceId]);}
 #[NoAdminRequired,NoCSRFRequired] public function invoiceDetail(int $id):TemplateResponse{$this->permissions->assert('invoices');$invoice=$this->one('re_erp_invoices',$id);if(!$invoice)throw new \InvalidArgumentException('Rechnung nicht gefunden.');return new TemplateResponse($this->appName,'invoice_detail',['invoice'=>$invoice,'customer'=>$this->one('re_erp_customers',(int)$invoice['customer_id']),'project'=>$invoice['project_id']?$this->one('re_erp_projects',(int)$invoice['project_id']):null,'items'=>$this->where('re_erp_invoice_items','invoice_id',$id,'id')]);}
