 #[NoAdminRequired,NoCSRFRequired] public function settings():TemplateResponse{$this->permissions->assert('settings');$logo=$this->folders->companyLogo();return new TemplateResponse($this->appName,'settings',['uid'=>$this->uid(),'logoPath'=>$logo['path']??null,'logoDataUri'=>$logo?'data:'.$logo['mime'].';base64,'.base64_encode($logo['content']):null,'hourlyRates'=>$this->hourlyRates()]);}
 #[NoAdminRequired] public function saveSettings():RedirectResponse{$this->permissions->assert('settings');$upload=$this->request->getUploadedFile('companyLogo');if(!$upload||empty($upload['tmp_name'])||!is_uploaded_file($upload['tmp_name']))throw new \InvalidArgumentException('Bitte eine Logo-Datei auswählen.');if(($upload['error']??UPLOAD_ERR_OK)!==UPLOAD_ERR_OK)throw new \InvalidArgumentException('Das Logo konnte nicht hochgeladen werden.');if(($upload['size']??0)>5*1024*1024)throw new \InvalidArgumentException('Das Logo darf maximal 5 MB groß sein.');$info=@getimagesize($upload['tmp_name']);$mime=$info['mime']??'';$ext=$mime==='image/png'?'png':($mime==='image/jpeg'?'jpg':'');if($ext==='')throw new \InvalidArgumentException('Erlaubt sind PNG und JPG.');$content=file_get_contents($upload['tmp_name']);if($content===false)throw new \RuntimeException('Das Logo konnte nicht gelesen werden.');$this->folders->saveCompanyLogo($content,$ext);$this->syncAllReportFiles();return $this->go('reinhardterp.module.settings');}

 #[NoAdminRequired] public function saveHourlyRate(?int $id,string $name,string $code,float $salesRate,float $costRate=0,?string $validFrom=null,int $active=1):RedirectResponse{$this->permissions->assert('settings');$name=trim($name);$code=strtoupper(trim($code));if($name===''||$code==='')throw new \InvalidArgumentException('Bezeichnung und Kürzel sind erforderlich.');if($salesRate<0||$costRate<0)throw new \InvalidArgumentException('Stundensätze dürfen nicht negativ sein.');$data=['name'=>$name,'code'=>$code,'sales_rate'=>$salesRate,'cost_rate'=>$costRate>0?$costRate:null,'valid_from'=>$validFrom?:null,'active'=>$active===1?1:0];if($id&&$id>0)$this->update('re_erp_hourly_rates',$id,$data);else{$data['created_at']=date('Y-m-d H:i:s');$this->insert('re_erp_hourly_rates',$data);}return $this->go('reinhardterp.module.settings');}
 private function writeReportSnapshot(int $id):void{
  $r=$this->one('re_erp_reports',$id);if(!$r)return;
  $p=$this->one('re_erp_projects',(int)$r['project_id']);if(!$p)return;
  $c=$this->one('re_erp_customers',(int)$p['customer_id']);
  $projectPath=trim((string)($p['folder_path']??''),'/');
  if($projectPath===''){
   if(!$c)return;
   $customerPath=trim((string)($c['folder_path']??''),'/');
   if($customerPath===''){$customerPath=$this->folders->ensureCustomerFolder((string)($c['customer_no']??''),(string)($c['name']??'Kunde'));$this->update('re_erp_customers',(int)$c['id'],['folder_path'=>$customerPath]);}
   $projectPath=$this->folders->ensureProjectFolder($customerPath,(string)($p['project_no']??''),(string)($p['title']??'Projekt'));
   $this->update('re_erp_projects',(int)$p['id'],['folder_path'=>$projectPath]);
  }
  $folderPath=trim((string)($r['folder_path']??''),'/');
  if($folderPath===''){$folderPath=$this->folders->ensureReportFolder($projectPath,(string)$r['report_no'],(string)$r['title']);}
  else{$folderPath=$this->folders->ensureReportFolder($projectPath,(string)$r['report_no'],(string)$r['title']);}
  $hours=$this->where('re_erp_report_hours','report_id',$id,'id');$items=$this->where('re_erp_report_items','report_id',$id,'id');$files=$this->where('re_erp_report_files','report_id',$id,'id');
  $html=$this->snapshotHtml($r,$p,$c,$hours,$items);
  $detailPath=$this->folders->write($folderPath,(string)$r['report_no'].'_Rapport.html',$html);
  $logo=$this->folders->companyLogo();
  $pdf=$this->pdf->createReport($r,$p,$c,$hours,$items,$logo);
  $pdfName=(string)$r['report_no'].'_Rapport.pdf';
  $pdfPath=$this->folders->write($folderPath,$pdfName,$pdf);
  $rootPath=$this->folders->ensureReportRoot($projectPath);
  $visibleName=(string)$r['report_no'].'_'.(string)$r['title'].'.pdf';
  $visiblePath=$this->folders->write($rootPath,$visibleName,$pdf);
  $json=json_encode(['schema'=>'reinhardterp.report.v1','report'=>$this->publicReportData($r),'customer'=>$c,'project'=>$p,'hours'=>$hours,'materials'=>$items,'files'=>$files],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
  if($json!==false)$this->folders->write($folderPath,'Rapport.json',$json);
  $this->update('re_erp_reports',$id,['folder_path'=>$folderPath,'print_path'=>$pdfPath,'updated_at'=>(string)($r['updated_at']??date('Y-m-d H:i:s'))]);
 }
 private function syncAllReportFiles():void{foreach($this->rows('re_erp_reports','id') as $r){try{$this->writeReportSnapshot((int)$r['id']);}catch(\Throwable $e){}}}
 private function publicReportData(array $r):array{unset($r['signature_data']);return $r;}
 private function snapshotHtml(array $r,?array $p,?array $c,array $hours,array $items):string{$e=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$logo=$this->folders->companyLogo();$logoHtml=$logo?'<img src="data:'.$e($logo['mime']).';base64,'.base64_encode($logo['content']).'" alt="Firmenlogo" style="max-width:210px;max-height:80px;object-fit:contain">':'<strong>Schreinerei Reinhardt</strong>';$h='<!doctype html><html lang="de"><meta charset="utf-8"><title>'.$e($r['report_no']).'</title><style>body{font:15px Arial;max-width:900px;margin:35px auto;color:#222}header{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:2px solid #555;padding-bottom:14px;margin-bottom:20px}h1,h2,h3{color:#222}h1{margin:0 0 4px}table{width:100%;border-collapse:collapse;margin:18px 0}th,td{border:1px solid #aaa;padding:8px;text-align:left}th{background:#eee}.meta{background:#f5f5f5;border:1px solid #ccc;padding:16px}.sign{margin-top:40px}</style><body><header><div><h1>Rapport '.$e($r['report_no']).'</h1><div>'.$e($r['title']).'</div></div><div>'.$logoHtml.'</div></header><div class="meta"><b>Kunde:</b> '.$e($c['customer_no']??'').' '.$e($c['name']??'').'<br><b>Projekt:</b> '.$e($p['project_no']??'').' '.$e($p['title']??'').'<br><b>Datum:</b> '.$e($r['report_date']).'<br><b>Status:</b> '.$e($r['status']).'</div><h2>Ausgeführte Arbeiten</h2><p>'.nl2br($e($r['description']??'')).'</p>'.(!empty($r['customer_note'])?'<h3>Hinweis für den Auftraggeber</h3><p>'.nl2br($e($r['customer_note'])).'</p>':'').'<h2>Arbeitszeiten</h2><table><tr><th>Mitarbeiter</th><th>Stunden</th><th>Tätigkeit</th></tr>';foreach($hours as $x)$h.='<tr><td>'.$e($x['user_id']).'</td><td>'.$e($x['hours']).'</td><td>'.$e($x['activity']).'</td></tr>';$h.='</table><h2>Material</h2><table><tr><th>Beschreibung</th><th>Menge</th><th>Einheit</th></tr>';foreach($items as $x)$h.='<tr><td>'.$e($x['description']).'</td><td>'.$e($x['quantity']).'</td><td>'.$e($x['unit']).'</td></tr>';$h.='</table><div class="sign"><b>Unterschrift:</b> '.$e($r['signed_by']??'noch nicht unterschrieben').'</div></body></html>';return $h;}
 private function reportRows():array{$qb=$this->db->getQueryBuilder();$qb->select('r.*','p.project_no','p.title AS project_title','c.name AS customer_name')->from('re_erp_reports','r')->leftJoin('r','re_erp_projects','p',$qb->expr()->eq('p.id','r.project_id'))->leftJoin('p','re_erp_customers','c',$qb->expr()->eq('c.id','p.customer_id'))->orderBy('r.report_date','DESC');return $qb->executeQuery()->fetchAllAssociative();}
 private function usersArray():array{$users=[];$this->userManager->callForSeenUsers(function($user)use(&$users){$users[]=['uid'=>$user->getUID(),'displayName'=>$user->getDisplayName(),'isAdmin'=>$this->groupManager->isAdmin($user->getUID())];});return $users;}
 private function activeErpUsers():array{$all=$this->usersArray();$out=[];foreach($all as $u){if($this->permissions->isEnabled($u['uid']))$out[]=$u;}usort($out,fn($a,$b)=>strcasecmp($a['displayName'],$b['displayName']));return $out;}
 private function workdayRows(string $from,string $to):array{$qb=$this->db->getQueryBuilder();$qb->select('w.id','w.user_id','w.entered_by','w.work_date','w.start_time','w.end_time','w.break_minutes','w.notes','e.activity','e.hours','e.project_id','e.imported_to_report_id','p.project_no','p.title')->from('re_erp_workdays','w')->leftJoin('w','re_erp_workday_entries','e',$qb->expr()->eq('e.workday_id','w.id'))->leftJoin('e','re_erp_projects','p',$qb->expr()->eq('p.id','e.project_id'))->where($qb->expr()->gte('w.work_date',$qb->createNamedParameter($from)))->andWhere($qb->expr()->lte('w.work_date',$qb->createNamedParameter($to)))->orderBy('w.work_date','DESC')->addOrderBy('w.start_time','DESC')->setMaxResults(500);return $qb->executeQuery()->fetchAllAssociative();}
 private function weeklySummary(string $from,string $to):array{$rows=$this->workdayRows($from,$to);$users=[];$days=[];$total=0.0;foreach($rows as $r){$h=(float)($r['hours']??0);$uid=(string)$r['user_id'];$date=(string)$r['work_date'];$users[$uid]=($users[$uid]??0)+$h;$days[$date]=($days[$date]??0)+$h;$total+=$h;}ksort($days);arsort($users);return ['total'=>$total,'users'=>$users,'days'=>$days];}
 private function activeTimers():array{$qb=$this->db->getQueryBuilder();$qb->select('t.*','p.project_no','p.title')->from('re_erp_time_timers','t')->leftJoin('t','re_erp_projects','p',$qb->expr()->eq('p.id','t.project_id'))->where($qb->expr()->in('t.status',[$qb->createNamedParameter('running'),$qb->createNamedParameter('paused')]))->orderBy('t.started_at','ASC');return $qb->executeQuery()->fetchAllAssociative();}
 private function normalizeWeekStart(?string $week):string{$ts=$week&&preg_match('/^\\d{4}-\\d{2}-\\d{2}$/',$week)?strtotime($week):time();$day=(int)date('N',$ts);return date('Y-m-d',strtotime('-'.($day-1).' days',$ts));}
 private function timeEvaluationRows(string $from,string $to,?int $customerId,?int $projectId,?string $userId,string $billingStatus):array{$qb=$this->db->getQueryBuilder();$qb->select('e.id','e.customer_id','e.project_id','e.activity','e.hours','e.imported_to_report_id','e.billing_status','e.billing_rate','e.billing_reference','e.billed_at','e.billed_by','w.user_id','w.work_date','w.start_time','w.end_time','w.break_minutes','w.entered_by','p.project_no','p.title AS project_title','p.special_hourly_rate','c.customer_no','c.name AS customer_name','ur.individual_hourly_rate','hr.sales_rate AS group_sales_rate','hr.name AS hourly_rate_name')->from('re_erp_workday_entries','e')->innerJoin('e','re_erp_workdays','w',$qb->expr()->eq('w.id','e.workday_id'))->leftJoin('e','re_erp_projects','p',$qb->expr()->eq('p.id','e.project_id'))->leftJoin('e','re_erp_customers','c',$qb->expr()->eq('c.id','e.customer_id'))->leftJoin('w','re_erp_user_roles','ur',$qb->expr()->eq('ur.user_id','w.user_id'))->leftJoin('ur','re_erp_hourly_rates','hr',$qb->expr()->eq('hr.id','ur.hourly_rate_id'))->where($qb->expr()->gte('w.work_date',$qb->createNamedParameter($from)))->andWhere($qb->expr()->lte('w.work_date',$qb->createNamedParameter($to)));if($customerId)$qb->andWhere($qb->expr()->eq('e.customer_id',$qb->createNamedParameter($customerId)));if($projectId)$qb->andWhere($qb->expr()->eq('e.project_id',$qb->createNamedParameter($projectId)));if($userId!==null&&$userId!=='')$qb->andWhere($qb->expr()->eq('w.user_id',$qb->createNamedParameter($userId)));if($billingStatus!=='all')$qb->andWhere($qb->expr()->eq('e.billing_status',$qb->createNamedParameter($billingStatus)));$qb->orderBy('c.name','ASC')->addOrderBy('p.project_no','ASC')->addOrderBy('w.work_date','ASC')->setMaxResults(2000);return $qb->executeQuery()->fetchAllAssociative();}
 private function availableTimeEntries(int $projectId):array{$qb=$this->db->getQueryBuilder();$qb->select('e.id','e.project_id','e.activity','e.hours','w.user_id','w.work_date')->from('re_erp_workday_entries','e')->innerJoin('e','re_erp_workdays','w',$qb->expr()->eq('w.id','e.workday_id'))->where($qb->expr()->eq('e.project_id',$qb->createNamedParameter($projectId)))->andWhere($qb->expr()->orX($qb->expr()->isNull('e.imported_to_report_id'),$qb->expr()->eq('e.imported_to_report_id',$qb->createNamedParameter(0))))->orderBy('w.work_date','ASC')->addOrderBy('e.id','ASC');$rows=$qb->executeQuery()->fetchAllAssociative();foreach($rows as &$row){$user=$this->userManager->get((string)$row['user_id']);$row['display_name']=$user?->getDisplayName()??(string)$row['user_id'];}unset($row);return $rows;}
 private function timeEntry(int $id):?array{$qb=$this->db->getQueryBuilder();$qb->select('e.*','w.user_id','w.work_date')->from('re_erp_workday_entries','e')->innerJoin('e','re_erp_workdays','w',$qb->expr()->eq('w.id','e.workday_id'))->where($qb->expr()->eq('e.id',$qb->createNamedParameter($id)));$r=$qb->executeQuery()->fetchAssociative();return $r?:null;}
 private function billingBatches():array{$qb=$this->db->getQueryBuilder();$qb->select('b.*','c.customer_no','c.name AS customer_name','p.project_no','p.title AS project_title')->from('re_erp_billing_batches','b')->leftJoin('b','re_erp_customers','c',$qb->expr()->eq('c.id','b.customer_id'))->leftJoin('b','re_erp_projects','p',$qb->expr()->eq('p.id','b.project_id'))->orderBy('b.id','DESC');return $qb->executeQuery()->fetchAllAssociative();}
 private function billingBatchItems(int $batchId):array{$qb=$this->db->getQueryBuilder();$qb->select('i.*')->from('re_erp_billing_batch_items','i')->where($qb->expr()->eq('i.batch_id',$qb->createNamedParameter($batchId)))->orderBy('i.work_date','ASC');$items=$qb->executeQuery()->fetchAllAssociative();foreach($items as &$i){$u=$this->userManager->get((string)$i['user_id']);$i['display_name']=$u?->getDisplayName()??(string)$i['user_id'];}unset($i);return $items;}
 private function writeBillingBatchSnapshot(int $id):void{$b=$this->one('re_erp_billing_batches',$id);if(!$b||empty($b['folder_path']))return;$customer=$this->one('re_erp_customers',(int)$b['customer_id']);$project=$b['project_id']?$this->one('re_erp_projects',(int)$b['project_id']):null;$items=$this->billingBatchItems($id);$html='<html><head><meta charset="utf-8"><style>body{font-family:Arial;color:#222;margin:40px}table{width:100%;border-collapse:collapse}th,td{padding:9px;border-bottom:1px solid #bbb;text-align:left}.num{text-align:right}.hint{margin-top:25px;padding:12px;background:#f3f3f3;border:1px solid #999}</style></head><body><h1>Abrechnungsvorbereitung '.htmlspecialchars((string)$b['batch_no']).'</h1><p>'.htmlspecialchars((string)($customer['name']??'')).'<br>Projekt: '.htmlspecialchars((string)($project['project_no']??'')).' '.htmlspecialchars((string)($project['title']??'')).'</p><table><tr><th>Datum</th><th>Mitarbeiter</th><th>Tätigkeit</th><th class="num">Stunden</th><th class="num">Satz</th><th class="num">Arbeitswert</th></tr>';foreach($items as $i)$html.='<tr><td>'.date('d.m.Y',strtotime((string)$i['work_date'])).'</td><td>'.htmlspecialchars((string)($i['display_name']??$i['user_id'])).'</td><td>'.htmlspecialchars((string)$i['activity']).'</td><td class="num">'.number_format((float)$i['hours'],2,',','.').'</td><td class="num">'.number_format((float)$i['hourly_rate'],2,',','.').' €</td><td class="num">'.number_format((float)$i['amount'],2,',','.').' €</td></tr>';$html.='</table><p style="text-align:right"><strong>'.number_format((float)$b['total_hours'],2,',','.').' Stunden</strong><br>Arbeitswert netto: <strong>'.number_format((float)$b['net_amount'],2,',','.').' €</strong></p><div class="hint"><strong>Interne Abrechnungsvorbereitung – keine Rechnung.</strong></div></body></html>';$this->folders->write((string)$b['folder_path'],(string)$b['batch_no'].'_Abrechnungsliste.html',$html);}
 private function invoiceTimeRow(int $id):?array{$qb=$this->db->getQueryBuilder();$qb->select('e.id','e.customer_id','e.project_id','e.activity','e.hours','e.billing_status','e.billing_rate','w.user_id','w.work_date','p.special_hourly_rate','c.customer_no','c.name AS customer_name','p.project_no','p.title AS project_title','ur.individual_hourly_rate','hr.sales_rate AS group_sales_rate')->from('re_erp_workday_entries','e')->innerJoin('e','re_erp_workdays','w',$qb->expr()->eq('w.id','e.workday_id'))->leftJoin('e','re_erp_projects','p',$qb->expr()->eq('p.id','e.project_id'))->leftJoin('e','re_erp_customers','c',$qb->expr()->eq('c.id','e.customer_id'))->leftJoin('w','re_erp_user_roles','ur',$qb->expr()->eq('ur.user_id','w.user_id'))->leftJoin('ur','re_erp_hourly_rates','hr',$qb->expr()->eq('hr.id','ur.hourly_rate_id'))->where($qb->expr()->eq('e.id',$qb->createNamedParameter($id)));$r=$qb->executeQuery()->fetchAssociative();return $r?:null;}
 private function writeInvoiceSnapshot(int $id):void{$invoice=$this->one('re_erp_invoices',$id);if(!$invoice)return;$customer=$this->one('re_erp_customers',(int)$invoice['customer_id']);$project=$invoice['project_id']?$this->one('re_erp_projects',(int)$invoice['project_id']):null;$items=$this->where('re_erp_invoice_items','invoice_id',$id,'id');$html='<html><head><meta charset="utf-8"><style>body{font-family:Arial;color:#222;margin:40px}table{width:100%;border-collapse:collapse}th,td{padding:9px;border-bottom:1px solid #bbb;text-align:left}.num{text-align:right}</style></head><body><h1>Rechnungsentwurf '.htmlspecialchars((string)$invoice['invoice_no']).'</h1><p>'.htmlspecialchars((string)($customer['name']??'')).'<br>'.nl2br(htmlspecialchars((string)($customer['address']??''))).'</p><p>Projekt: '.htmlspecialchars((string)($project['project_no']??'')).' '.htmlspecialchars((string)($project['title']??'')).'</p><table><tr><th>Leistung</th><th>Einheit</th><th class="num">Menge</th><th class="num">Einzelpreis</th><th class="num">Gesamt</th></tr>';foreach($items as $i)$html.='<tr><td>'.htmlspecialchars((string)$i['description']).'</td><td>'.htmlspecialchars((string)$i['unit']).'</td><td class="num">'.number_format((float)$i['quantity'],2,',','.').'</td><td class="num">'.number_format((float)$i['unit_price'],2,',','.').' €</td><td class="num">'.number_format((float)$i['total_price'],2,',','.').' €</td></tr>';$html.='</table><p style="text-align:right">Netto: '.number_format((float)$invoice['net_amount'],2,',','.').' €<br>USt. '.number_format((float)$invoice['vat_rate'],2,',','.').' %<br><strong>Brutto: '.number_format((float)$invoice['gross_amount'],2,',','.').' €</strong></p></body></html>';$this->folders->write((string)$invoice['folder_path'],(string)$invoice['invoice_no'].'_Entwurf.html',$html);}
 private function timeBillingRow(int $id):?array{$qb=$this->db->getQueryBuilder();$qb->select('e.billing_rate','p.special_hourly_rate','ur.individual_hourly_rate','hr.sales_rate AS group_sales_rate')->from('re_erp_workday_entries','e')->innerJoin('e','re_erp_workdays','w',$qb->expr()->eq('w.id','e.workday_id'))->leftJoin('e','re_erp_projects','p',$qb->expr()->eq('p.id','e.project_id'))->leftJoin('w','re_erp_user_roles','ur',$qb->expr()->eq('ur.user_id','w.user_id'))->leftJoin('ur','re_erp_hourly_rates','hr',$qb->expr()->eq('hr.id','ur.hourly_rate_id'))->where($qb->expr()->eq('e.id',$qb->createNamedParameter($id)));$r=$qb->executeQuery()->fetchAssociative();return $r?:null;}
 private function automaticRate(?array $row):?float{if(!$row)return null;foreach(['billing_rate','special_hourly_rate','individual_hourly_rate','group_sales_rate'] as $key)if($row[$key]!==null&&(float)$row[$key]>0)return (float)$row[$key];return null;}
 private function hourlyRates():array{$qb=$this->db->getQueryBuilder();$qb->select('*')->from('re_erp_hourly_rates')->orderBy('active','DESC')->addOrderBy('name','ASC');return $qb->executeQuery()->fetchAllAssociative();}
 private function page(string $template,string $title,array $rows,array $extra=[]):TemplateResponse{return new TemplateResponse($this->appName,$template,array_merge(['title'=>$title,'rows'=>$rows],$extra));}
 private function rows(string $table,string $order):array{$qb=$this->db->getQueryBuilder();$qb->select('*')->from($table)->orderBy($order,'DESC')->setMaxResults(250);return $qb->executeQuery()->fetchAllAssociative();}
 private function where(string $table,string $column,int $value,string $order):array{$qb=$this->db->getQueryBuilder();$qb->select('*')->from($table)->where($qb->expr()->eq($column,$qb->createNamedParameter($value)))->orderBy($order,'ASC');return $qb->executeQuery()->fetchAllAssociative();}
 private function one(string $table,int $id):?array{$qb=$this->db->getQueryBuilder();$qb->select('*')->from($table)->where($qb->expr()->eq('id',$qb->createNamedParameter($id)));$r=$qb->executeQuery()->fetchAssociative();return $r?:null;}
 private function insert(string $table,array $data):int{$qb=$this->db->getQueryBuilder();$qb->insert($table);foreach($data as $k=>$v)$qb->setValue($k,$qb->createNamedParameter($v));$qb->executeStatement();return (int)$this->db->lastInsertId($table);}
 private function update(string $table,int $id,array $data):void{$qb=$this->db->getQueryBuilder();$qb->update($table);foreach($data as $k=>$v)$qb->set($k,$qb->createNamedParameter($v));$qb->where($qb->expr()->eq('id',$qb->createNamedParameter($id)))->executeStatement();}
 private function delete(string $table,int $id):void{$qb=$this->db->getQueryBuilder();$qb->delete($table)->where($qb->expr()->eq('id',$qb->createNamedParameter($id)))->executeStatement();}
 private function assertEditable(?array $report):void{if(!$report)throw new \InvalidArgumentException('Rapport nicht gefunden.');if(!empty($report['locked']))throw new \InvalidArgumentException('Dieser Rapport ist abgeschlossen und gesperrt. Bitte zuerst wieder öffnen.');}
 private function uid():string{return $this->session->getUser()?->getUID()??'system';}
 private function go(string $route,array $params=[]):RedirectResponse{return new RedirectResponse($this->url->linkToRoute($route,$params));}
}
